INSERT INTO preguntas (categoria, pregunta, opciones, respuesta, explicacion, activa) VALUES
  ('Señales', '¿Qué indica una señal de PARE (octagonal roja)?', '["Reducir la velocidad", "Detenerse completamente antes de la línea de pare", "Ceder el paso solo si hay vehículos", "Continuar con precaución"]'::jsonb, 1, 'La señal PARE obliga al conductor a detenerse totalmente antes de la línea de detención o del cruce peatonal.', true),
  ('Señales', '¿Qué significa una señal circular con borde rojo y número 60?', '["Velocidad mínima permitida", "Velocidad máxima permitida", "Distancia en metros", "Zona escolar a 60 metros"]'::jsonb, 1, 'Las señales circulares con borde rojo y número indican velocidad máxima permitida en ese tramo.', true),
  ('Señales', '¿Qué indica una señal triangular con borde rojo y vértice hacia abajo?', '["Peligro adelante", "Ceda el paso", "Zona escolar", "Curva peligrosa"]'::jsonb, 1, 'El triángulo invertido con borde rojo es la señal de CEDA EL PASO, que obliga a dar preferencia a otros vehículos.', true),
  ('Señales', '¿Qué color tienen las señales informativas en Colombia?', '["Rojo", "Amarillo", "Verde o azul", "Naranja"]'::jsonb, 2, 'Las señales informativas son verdes (para rutas) o azules (para servicios y zonas urbanas).', true),
  ('Señales', '¿Qué indica una señal amarilla en forma de diamante?', '["Prohibición", "Obligación", "Prevención o advertencia", "Información"]'::jsonb, 2, 'Las señales amarillas en rombo (diamante) son preventivas, advierten sobre condiciones peligrosas adelante.', true),
  ('Señales', '¿Qué significa una X en la carretera antes de un cruce de ferrocarril?', '["Zona de parqueo", "Cruce de peatones", "Cruce de línea férrea sin barrera", "Fin de vía"]'::jsonb, 2, 'La X pintada en la vía indica aproximación a un cruce ferroviario, advirtiendo al conductor que debe reducir velocidad.', true),
  ('Señales', '¿Qué indica una señal de flecha amarilla parpadeante en semáforo?', '["Avanzar sin detenerse", "Giro permitido con precaución cediendo el paso a peatones", "Giro prohibido", "Esperar luz verde"]'::jsonb, 1, 'La flecha amarilla parpadeante permite el giro pero el conductor debe ceder el paso a peatones y ciclistas.', true),
  ('Señales', '¿Qué señal indica que está prohibido adelantar?', '["Línea blanca discontinua al centro", "Línea amarilla continua al centro", "Línea azul lateral", "Doble línea blanca"]'::jsonb, 1, 'La línea amarilla continua al centro de la calzada prohíbe adelantar o invadir el carril contrario.', true),
  ('Señales', '¿Qué significa la luz roja del semáforo?', '["Reducir velocidad", "Continuar con precaución", "Detenerse obligatoriamente", "Ceder el paso"]'::jsonb, 2, 'La luz roja obliga a detenerse completamente antes de la línea de pare o la intersección.', true),
  ('Señales', '¿Qué indica la luz verde del semáforo?', '["Avanzar si no hay obstáculos", "Girar siempre a la derecha", "Acelerar al máximo", "Detenerse"]'::jsonb, 0, 'La luz verde indica que puede avanzar, pero siempre verificando que la vía esté libre y cediendo el paso donde corresponda.', true),
  ('Normas', '¿Cuál es la velocidad máxima permitida en zonas residenciales urbanas en Colombia?', '["30 km/h", "40 km/h", "50 km/h", "60 km/h"]'::jsonb, 0, 'Según el Código Nacional de Tránsito, en zonas residenciales la velocidad máxima es 30 km/h.', true),
  ('Normas', '¿Cuál es la velocidad máxima en carretera (vía primaria) de dos carriles?', '["80 km/h", "100 km/h", "120 km/h", "60 km/h"]'::jsonb, 1, 'En carreteras primarias de dos carriles bidireccionales la velocidad máxima es 100 km/h para automóviles.', true),
  ('Normas', '¿A qué distancia mínima se debe encender las luces altas en la noche?', '["50 metros", "100 metros", "150 metros", "200 metros"]'::jsonb, 1, 'Las luces altas deben encenderse cuando no haya visibilidad suficiente a 100 metros de distancia.', true),
  ('Normas', '¿Cuándo se debe usar la bocina del vehículo?', '["Para saludar a conocidos", "En zonas escolares para alertar", "Solo en casos necesarios de seguridad vial", "Siempre que se adelante un vehículo"]'::jsonb, 2, 'La bocina solo debe usarse para prevenir accidentes. Su uso innecesario está prohibido especialmente en zonas hospitalarias y residenciales.', true),
  ('Normas', '¿Qué debe hacer el conductor al llegar a un cruce sin señalización?', '["Quien llega primero tiene prioridad", "Ceder el paso al vehículo de la derecha", "Ceder el paso al vehículo de la izquierda", "El vehículo más grande tiene prioridad"]'::jsonb, 1, 'En intersecciones sin señalización, se debe ceder el paso al vehículo que viene por la derecha.', true),
  ('Normas', '¿Con qué BAC (gramos de alcohol por litro de sangre) se considera conducción en estado de embriaguez en Colombia?', '["Más de 0.2 g/L", "Más de 0.4 g/L", "Más de 0.8 g/L", "Más de 1.0 g/L"]'::jsonb, 1, 'Según la Ley 1696 de 2013, conducir con 0.4 g/L o más en sangre es conducción en estado de embriaguez.', true),
  ('Normas', '¿Cuándo es obligatorio el uso del cinturón de seguridad?', '["Solo en carretera", "Solo el conductor", "Todos los ocupantes siempre", "Solo en viajes largos"]'::jsonb, 2, 'El cinturón de seguridad es obligatorio para todos los ocupantes del vehículo en todo momento.', true),
  ('Normas', '¿Qué se debe hacer al acercarse a un vehículo de emergencia con sirena activa?', '["Acelerar para despejar la vía", "Orillarse a la derecha y detenerse", "Continuar normalmente", "Activar las luces de emergencia y acelerar"]'::jsonb, 1, 'Ante vehículos de emergencia con sirena y luces, el conductor debe orillarse a la derecha y detenerse.', true),
  ('Normas', '¿Cuántos metros mínimos antes de girar se deben encender las direccionales?', '["10 metros", "20 metros", "30 metros", "50 metros"]'::jsonb, 2, 'Las señales de giro (direccionales) deben activarse al menos 30 metros antes de efectuar la maniobra.', true),
  ('Normas', '¿Qué distancia mínima debe mantener con el vehículo de adelante?', '["La que permite detenerse de forma segura", "2 metros", "5 metros", "10 metros"]'::jsonb, 0, 'La distancia de seguimiento debe permitir detenerse de forma segura. Se recomienda la regla de los 3 segundos.', true),
  ('Licencias', '¿Qué categoría de licencia se requiere para conducir una motocicleta de más de 125cc?', '["A1", "A2", "B1", "C1"]'::jsonb, 1, 'La categoría A2 habilita para conducir motocicletas de más de 125cc. La A1 es para motos de hasta 125cc.', true),
  ('Licencias', '¿Qué categoría de licencia necesita un conductor de bus intermunicipal?', '["B1", "B2", "C1", "C2"]'::jsonb, 2, 'La categoría C1 habilita para conducir vehículos de transporte público de pasajeros y de carga liviana.', true),
  ('Licencias', '¿Qué edad mínima se requiere para obtener licencia B1 (particular) en Colombia?', '["15 años", "16 años", "18 años", "21 años"]'::jsonb, 1, 'Para obtener la licencia de conducción categoría B1 se requiere mínimo 16 años en Colombia.', true),
  ('Licencias', '¿Cada cuántos años se debe renovar la licencia de conducción en Colombia?', '["3 años", "5 años", "10 años", "No se renueva"]'::jsonb, 2, 'Según la normativa, la licencia de conducción debe renovarse cada 10 años para la mayoría de categorías.', true),
  ('Licencias', '¿Qué documento expide el CEA al aprobar el curso de conducción?', '["La licencia de conducción definitiva", "El certificado de aptitud", "El SOAT", "La tarjeta de propiedad"]'::jsonb, 1, 'El CEA expide el Certificado de Aptitud en Conducción que habilita al estudiante para tramitar su licencia ante el organismo de tránsito.', true),
  ('Mecánica', '¿Qué indica la luz del aceite encendida en el tablero?', '["Cambiar el aceite próximamente", "Presión de aceite baja o sin aceite — detenerse inmediatamente", "Aceite de motor caliente", "Revisar el filtro de aire"]'::jsonb, 1, 'La luz de aceite indica presión insuficiente. Continuar conduciendo puede destruir el motor; debe detenerse de inmediato.', true),
  ('Mecánica', '¿Con qué frecuencia aproximada se debe revisar la presión de los neumáticos?', '["Una vez al año", "Cada 6 meses", "Mensualmente o antes de viajes largos", "Cada 5 años"]'::jsonb, 2, 'Se recomienda revisar la presión de los neumáticos mensualmente y antes de cada viaje largo.', true),
  ('Mecánica', '¿Qué función tiene el líquido refrigerante del motor?', '["Lubricar las piezas del motor", "Regular la temperatura del motor evitando el sobrecalentamiento", "Limpiar el sistema de frenos", "Transmitir la potencia"]'::jsonb, 1, 'El refrigerante mantiene la temperatura del motor dentro del rango óptimo, evitando sobrecalentamiento o congelamiento.', true),
  ('Mecánica', '¿Qué hacer si los frenos del vehículo fallan durante la marcha?', '["Apagar el motor inmediatamente", "Reducir marchas, usar el freno de mano progresivamente y buscar una salida segura", "Abrir la puerta para frenar", "Acelerar para ganar control"]'::jsonb, 1, 'En falla de frenos: reducir marchas, aplicar freno de mano progresivamente, buscar zona de escape (subida o arena) y avisar con bocina.', true),
  ('Mecánica', '¿Cuál es la profundidad mínima legal del dibujo del neumático en Colombia?', '["0.8 mm", "1.6 mm", "2.0 mm", "3.2 mm"]'::jsonb, 1, 'La profundidad mínima legal del dibujo del neumático es 1.6 mm. Menos de esto representa peligro por pérdida de adherencia.', true),
  ('Primeros Auxilios', 'Al llegar a un accidente de tránsito, ¿cuál es el primer paso?', '["Mover a los heridos de la vía", "Asegurar la escena y llamar a emergencias (123)", "Dar agua a los heridos", "Tomar fotos del accidente"]'::jsonb, 1, 'Lo primero es asegurar la escena (señalizar) y activar el sistema de emergencias llamando al 123 para atención especializada.', true),
  ('Primeros Auxilios', '¿Cuándo NO se debe mover a un accidentado?', '["Cuando hay riesgo de incendio", "Cuando está inconsciente", "Siempre que haya trauma en columna o cabeza, a menos que haya peligro inminente", "Cuando ya recibió primeros auxilios"]'::jsonb, 2, 'No se debe mover a un accidentado con sospecha de trauma en columna o cabeza, salvo riesgo vital como incendio o ahogamiento.', true),
  ('Primeros Auxilios', '¿Cómo se detiene una hemorragia externa?', '["Aplicar torniquete siempre", "Presión directa sostenida sobre la herida con tela limpia", "Lavar la herida con agua fría", "Elevar las piernas del herido"]'::jsonb, 1, 'La presión directa y sostenida sobre la herida es la forma más efectiva de controlar una hemorragia externa.', true),
  ('Primeros Auxilios', '¿Qué no se debe dar a una persona accidentada?', '["Apoyo emocional", "Alimentos o líquidos por vía oral", "Abrigo si tiene frío", "Mantenerla tranquila"]'::jsonb, 1, 'No se deben dar alimentos ni líquidos a un accidentado: puede necesitar cirugía urgente y podría causar aspiración.', true),
  ('Conducción Segura', '¿Qué es el fenómeno de ''aquaplaning''?', '["Exceso de velocidad en lluvia", "Pérdida de tracción por capa de agua entre neumático y calzada", "Fallo del sistema de frenos en mojado", "Condensación en el parabrisas"]'::jsonb, 1, 'El aquaplaning ocurre cuando los neumáticos pierden contacto con la calzada al formarse una capa de agua. Solución: soltar el acelerador suavemente.', true),
  ('Conducción Segura', '¿Cómo afecta la lluvia a la distancia de frenado?', '["No la afecta", "La reduce a la mitad", "La aumenta hasta el doble o más", "Mejora el frenado"]'::jsonb, 2, 'En piso mojado la distancia de frenado puede duplicarse o triplicarse, por lo que se debe reducir la velocidad.', true),
  ('Conducción Segura', '¿Qué se debe hacer al conducir en neblina densa?', '["Encender luces altas para ver mejor", "Usar luces bajas y neblineros, reducir velocidad y aumentar distancia", "Apagar todas las luces para no deslumbrar", "Conducir al centro de la vía"]'::jsonb, 1, 'En neblina se usan luces bajas y neblineros (no altas, rebotan), se reduce la velocidad y se aumenta la distancia de seguimiento.', true),
  ('Conducción Segura', '¿Qué es el punto ciego en un vehículo?', '["El retrovisor interior", "Zona que no es visible en ningún espejo del vehículo", "La parte trasera del vehículo", "El área frente al capó"]'::jsonb, 1, 'El punto ciego es la zona lateral-trasera que no aparece en ningún espejo. Siempre verificar girando la cabeza antes de cambiar de carril.', true),
  ('Conducción Segura', '¿Cuál es la posición correcta de las manos en el volante?', '["12 y 6 (arriba y abajo)", "9 y 3 (lados) o 10 y 2", "8 y 4", "Una mano al centro"]'::jsonb, 1, 'La posición 9 y 3 (o 10 y 2) ofrece mejor control del volante y permite reaccionar rápido en emergencias.', true),
  ('Motociclistas', '¿Es obligatorio el uso del casco para el parrillero de una motocicleta?', '["Solo en carretera", "No, solo el conductor", "Sí, siempre para conductor y pasajero", "Solo si la moto supera 125cc"]'::jsonb, 2, 'El casco es obligatorio para el conductor y todos los pasajeros de la motocicleta en toda vía pública.', true),
  ('Motociclistas', '¿Cuántas personas pueden viajar en una motocicleta legalmente?', '["Solo el conductor", "Conductor y un pasajero", "Hasta 3 personas si es moto grande", "Solo en motos de más de 250cc se permite pasajero"]'::jsonb, 1, 'En una motocicleta solo pueden viajar el conductor y UN pasajero, independientemente de la cilindrada.', true),
  ('Motociclistas', '¿Qué prenda de seguridad adicional se recomienda para motociclistas?', '["Solo el casco", "Casco, guantes, chaqueta reforzada, botas y pantalón de protección", "Chaleco reflectivo solo en la noche", "Gafas de sol"]'::jsonb, 1, 'El equipo completo incluye casco certificado, guantes, chaqueta con protecciones, botas y pantalón especializado.', true),
  ('Motociclistas', '¿Pueden las motos transitar por el carril exclusivo de bicicletas (ciclovía)?', '["Sí, si van despacio", "Sí, cuando el tráfico está congestionado", "No, está prohibido", "Solo motos eléctricas"]'::jsonb, 2, 'Las ciclovías y ciclocarriles son exclusivos para bicicletas, triciclos y vehículos de movilidad personal no motorizados.', true),
  ('Peatones', '¿Por dónde deben transitar los peatones en vías sin andén?', '["Al centro de la vía", "Por la derecha en el sentido del tráfico", "Por la izquierda enfrentando el tráfico", "Por cualquier lado"]'::jsonb, 2, 'En vías sin andén los peatones deben caminar por la izquierda, mirando de frente el tráfico que viene hacia ellos.', true),
  ('Peatones', '¿En qué lugar tiene prioridad absoluta el peatón?', '["En toda la vía pública", "Solo en parques", "En pasos peatonales demarcados", "Solo en zonas escolares"]'::jsonb, 2, 'En los cruces peatonales (cebras) debidamente demarcados, el peatón tiene derecho de vía prioritario.', true),
  ('Ciclistas', '¿Los ciclistas deben respetar los semáforos?', '["No, pueden continuar si no hay carros", "Sí, las mismas normas que los vehículos motorizados", "Solo los semáforos rojos", "Solo en vías primarias"]'::jsonb, 1, 'Los ciclistas están sujetos a las mismas normas de tránsito que los vehículos: deben respetar semáforos, señales y prioridades.', true),
  ('Ciclistas', '¿Es obligatorio el uso de chaleco reflectivo para ciclistas en la noche?', '["No es obligatorio", "Solo en carretera", "Sí, siempre al circular de noche en vía pública", "Solo en ciclistas menores de edad"]'::jsonb, 2, 'El chaleco o elementos reflectivos son obligatorios para ciclistas al circular en horario nocturno en cualquier vía.', true),
  ('Infracciones', '¿Qué tipo de infracción es pasar un semáforo en rojo?', '["Leve", "Grave", "Gravísima", "No es infracción si no hay peatones"]'::jsonb, 2, 'Pasar un semáforo en rojo es una infracción GRAVÍSIMA que puede generar suspensión de la licencia y multa alta.', true),
  ('Infracciones', '¿Cuál es la sanción por conducir bajo efectos del alcohol en Colombia?', '["Solo multa económica", "Multa, suspensión de licencia y posiblemente prisión según el nivel", "Advertencia verbal", "Solo retención del vehículo"]'::jsonb, 1, 'La Ley 1696/2013 establece multas progresivas, suspensión o cancelación de licencia y penas de prisión según el nivel de alcohol.', true),
  ('Infracciones', '¿Se puede usar el celular mientras se conduce?', '["Sí, con audífono", "Sí, solo para GPS", "No, está totalmente prohibido salvo dispositivos manos libres integrados al vehículo", "Solo en semáforos en rojo"]'::jsonb, 2, 'El uso del celular al conducir está prohibido. Solo se permite comunicación a través de sistemas integrados de manos libres del vehículo.', true),
  ('Infracciones', '¿Qué es el comparendo?', '["El seguro obligatorio del vehículo", "El documento que impone una sanción por infracción de tránsito", "La licencia de tránsito", "El certificado técnico-mecánico"]'::jsonb, 1, 'El comparendo es el documento mediante el cual el agente de tránsito reporta y notifica una infracción al conductor.', true),
  ('Documentos', '¿Qué es el SOAT?', '["Impuesto vehicular", "Seguro Obligatorio de Accidentes de Tránsito que cubre víctimas de accidentes", "Certificado técnico-mecánico", "Tarjeta de circulación"]'::jsonb, 1, 'El SOAT (Seguro Obligatorio de Accidentes de Tránsito) es obligatorio y cubre gastos médicos y de muerte de víctimas de accidentes.', true),
  ('Documentos', '¿Cada cuánto debe realizarse la revisión técnico-mecánica para vehículos particulares con más de 2 años?', '["Cada año", "Cada 2 años", "Cada 3 años", "Solo cuando el vehículo tenga problemas"]'::jsonb, 1, 'Los vehículos particulares con más de 2 años de fabricación deben pasar revisión técnico-mecánica cada 2 años (anual para servicio público).', true),
  ('Documentos', '¿Qué pasa si conduce sin SOAT vigente?', '["Solo advertencia verbal", "Inmovilización del vehículo y multa", "Solo multa pequeña", "No hay sanción"]'::jsonb, 1, 'Circular sin SOAT es infracción grave: el vehículo puede ser inmovilizado hasta que se acredite su adquisición además de la multa.', true),
  ('Normas', '¿Qué es la distancia de seguridad lateral?', '["La separación con el semáforo", "El espacio lateral mínimo al adelantar ciclistas o motocicletas (al menos 1 metro)", "La distancia al andén", "El ancho del carril"]'::jsonb, 1, 'Al adelantar a ciclistas o motociclistas se debe dejar al menos 1 metro de distancia lateral para su seguridad.', true),
  ('Normas', '¿Está permitido estacionarse en doble fila?', '["Sí, si es breve", "Sí, con luces de emergencia", "No, es una infracción", "Solo de noche"]'::jsonb, 2, 'El estacionamiento en doble fila está prohibido pues obstruye la vía. Es infracción sancionable con multa.', true),
  ('Normas', '¿Quién tiene prioridad en una rotonda (glorieta)?', '["El vehículo que entra", "El vehículo que ya está dentro de la glorieta", "El vehículo más grande", "Quien lleva más velocidad"]'::jsonb, 1, 'En las glorietas, tienen prioridad los vehículos que ya circulan dentro. Los que entran deben ceder el paso.', true),
  ('Normas', '¿Cuándo está permitido hacer cambio de carril?', '["En cualquier momento", "Cuando la línea central sea discontinua y haya espacio libre", "Solo en autopistas", "Nunca, solo en intersecciones"]'::jsonb, 1, 'El cambio de carril es permitido cuando la línea es discontinua, hay visibilidad suficiente, espacio libre y se señaliza con anticipación.', true),
  ('Normas', '¿Qué significa ''zona de no parqueo'' marcada en el pavimento?', '["Estacionamiento permitido 30 minutos", "Prohibición absoluta de estacionar", "Solo no parqueo en horas pico", "Zona de carga y descarga"]'::jsonb, 1, 'Las zonas demarcadas como ''no parqueo'' tienen prohibición absoluta de estacionar en cualquier momento.', true),
  ('Normas', '¿A qué velocidad máxima deben transitar los vehículos en zonas escolares?', '["20 km/h", "30 km/h", "40 km/h", "50 km/h"]'::jsonb, 0, 'En zonas escolares la velocidad máxima es 20 km/h para garantizar la seguridad de niños y peatones.', true),
  ('Normas', '¿Es obligatorio detenerse ante un bus escolar que está recogiendo o dejando estudiantes?', '["No, si circula en carril contrario", "Sí, en ambos sentidos hasta que el bus retome la marcha", "Solo si hay estudiantes cruzando", "Solo el carril del mismo sentido"]'::jsonb, 1, 'La ley obliga a todos los vehículos a detenerse en ambos sentidos mientras el bus escolar tiene luces intermitentes activas.', true),
  ('Normas', '¿Qué es el ''pico y placa''?', '["Restricción de velocidad en horas específicas", "Restricción de circulación según el último dígito de la placa en horario y zona determinados", "Impuesto de rodamiento", "Norma de revisión de frenos"]'::jsonb, 1, 'El pico y placa restringe la circulación de vehículos según el último dígito de su placa en horarios y zonas específicas para reducir la congestión.', true),
  ('Conducción Segura', '¿Qué es la conducción defensiva?', '["Conducir lo más rápido posible para llegar pronto", "Técnica que permite anticipar riesgos y actuar para evitar accidentes", "Conducir solo de día", "Usar siempre el carril derecho"]'::jsonb, 1, 'La conducción defensiva busca anticipar y evitar situaciones de riesgo, aún cuando otros cometan errores.', true),
  ('Conducción Segura', '¿Cuántos metros de visibilidad se requieren mínimo para adelantar?', '["50 metros", "100 metros", "200 metros", "400 metros"]'::jsonb, 2, 'Para adelantar con seguridad se requiere visibilidad de al menos 200 metros en línea recta y vía libre.', true),
  ('Conducción Segura', '¿Qué debe hacer si siente sueño conduciendo?', '["Bajar la ventanilla y continuar", "Tomar café y seguir", "Detenerse en lugar seguro y descansar", "Conducir más rápido para llegar pronto"]'::jsonb, 2, 'El sueño al volante es causa principal de accidentes. Debe detenerse en un lugar seguro y descansar antes de continuar.', true),
  ('Conducción Segura', '¿Qué es el ''efecto túnel'' en conducción?', '["Conducir por un túnel sin luces", "Reducción del campo visual periférico al aumentar la velocidad", "Deslumbramiento al salir de un túnel", "Pérdida de señal GPS"]'::jsonb, 1, 'A mayor velocidad, el campo visual se estrecha (efecto túnel), reduciendo la capacidad de detectar obstáculos laterales.', true),
  ('Conducción Segura', '¿Cómo afecta el cansancio al tiempo de reacción?', '["No lo afecta", "Lo mejora (el conductor se concentra más)", "Lo aumenta significativamente, retardando la respuesta ante peligros", "Solo afecta de noche"]'::jsonb, 2, 'El cansancio aumenta el tiempo de reacción, reduce la concentración y puede causar microsueños al volante.', true),
  ('Señales', '¿Qué indica una señal circular azul con flecha blanca?', '["Prohibición de girar", "Obligación de seguir la dirección indicada", "Recomendación de ruta", "Fin de restricción"]'::jsonb, 1, 'Las señales circulares azules con flechas blancas son OBLIGATORIAS: el conductor DEBE seguir la dirección indicada.', true),
  ('Señales', '¿Qué significa una señal rectangular azul con una ''P'' blanca?', '["Prohibición de parquear", "Zona de parqueo permitido", "Parqueadero de pago", "Parqueadero privado"]'::jsonb, 1, 'La señal azul con P blanca indica zona de parqueo permitido para los vehículos.', true),
  ('Señales', '¿Qué indica una señal de ''zona de derrumbes''?', '["Zona de construcción permanente", "Zona de riesgo por derrumbes o caída de rocas", "Área de minería", "Zona de vientos fuertes"]'::jsonb, 1, 'La señal de zona de derrumbes advierte que existe riesgo de caída de material de los taludes. Se debe reducir velocidad y estar alerta.', true),
  ('Señales', '¿Qué señal indica el inicio de una zona urbana?', '["Señal rectangular verde con nombre de ciudad", "Señal que reduce la velocidad máxima a 60 km/h", "Señal rectangular azul", "Líneas amarillas en la calzada"]'::jsonb, 0, 'El ingreso a zona urbana se indica con señal rectangular verde con el nombre del municipio o ciudad.', true),
  ('Normas', '¿Está prohibido circular en reversa en una autopista o vía de alta velocidad?', '["No, si hay emergencia", "Sí, absolutamente prohibido", "Solo si obstruye el tráfico", "Solo de noche"]'::jsonb, 1, 'Circular en reversa en autopistas o vías primarias es una infracción gravísima que pone en peligro la vida.', true),
  ('Normas', '¿Qué se debe hacer si un vehículo se queda varado en la vía?', '["Dejarlo en el carril y buscar ayuda", "Señalizar con triángulos de emergencia, alejarse del vehículo y llamar a grúa", "Empujarlo al arcén rápidamente", "Activar solo las luces de emergencia y esperar"]'::jsonb, 1, 'Debe señalizar con triángulos a distancia adecuada, alejarse del vehículo (riesgo de atropello) y llamar a servicio de grúa.', true),
  ('Normas', '¿A qué distancia deben colocarse los triángulos de emergencia?', '["5 metros", "10 metros", "Al menos 50 metros del vehículo", "100 metros"]'::jsonb, 2, 'Los triángulos de emergencia deben colocarse al menos a 50 metros del vehículo varado, en cada dirección si la vía es bidireccional.', true),
  ('Mecánica', '¿Para qué sirve el freno de mano o freno de estacionamiento?', '["Freno de emergencia principal", "Mantener el vehículo detenido en pendientes y estacionamiento", "Freno de las ruedas traseras en curvas", "Regular la presión del sistema de frenos"]'::jsonb, 1, 'El freno de mano evita que el vehículo se desplace al estar estacionado, especialmente en pendientes.', true),
  ('Mecánica', '¿Qué indica el testigo del ABS en el tablero?', '["Sistema de frenos antibloqueo funcionando correctamente", "Fallo en el sistema ABS que debe revisarse", "El ABS está desactivado intencionalmente", "Alerta de pastillas de freno desgastadas"]'::jsonb, 1, 'Si el testigo del ABS permanece encendido mientras se conduce, indica una falla en el sistema que debe revisarse urgentemente.', true),
  ('Mecánica', '¿Qué hace el sistema de frenos ABS?', '["Aumenta la potencia de frenado", "Impide que las ruedas se bloqueen en frenado brusco permitiendo seguir girando el volante", "Activa el freno de emergencia automáticamente", "Lubrica el sistema de frenos"]'::jsonb, 1, 'El ABS (Anti-lock Braking System) evita el bloqueo de ruedas en frenado brusco, manteniendo la dirección y reduciendo la distancia de frenado.', true),
  ('Conducción Segura', '¿Qué es la ''zona de crumple'' de un vehículo moderno?', '["El área de las bolsas de aire", "Zonas diseñadas para deformarse y absorber energía en un choque protegiendo a los ocupantes", "El cinturón de seguridad", "El vidrio laminado del parabrisas"]'::jsonb, 1, 'Las zonas de deformación programada absorben la energía del impacto y reducen la fuerza que llega al habitáculo y a los ocupantes.', true),
  ('Peatones', '¿Qué debe hacer un conductor cuando un peatón inicia el cruce en luz verde peatonal?', '["Tocar bocina para alertarlo", "Continuar si el peatón aún está en el andén", "Ceder el paso aunque el semáforo vehicular esté en verde", "Reducir velocidad pero continuar"]'::jsonb, 2, 'El peatón que cruce en luz verde peatonal tiene prioridad absoluta. El conductor debe ceder el paso completamente.', true),
  ('Normas', '¿Cuándo está permitido circular por el carril del centro en una vía de tres carriles?', '["Siempre, es el carril más rápido", "Solo para adelantar, retornando luego al carril derecho", "Está prohibido circular por el carril central", "Solo camiones y buses"]'::jsonb, 1, 'El carril central de una vía de tres carriles se usa para adelantar y luego se debe retornar al carril derecho.', true),
  ('Infracciones', '¿Qué es la inmovilización de un vehículo?', '["Quitar las llantas al vehículo", "Retención del vehículo en patio oficial por infracción grave o documentos vencidos", "Multa por mal estacionamiento", "Suspensión temporal de la licencia"]'::jsonb, 1, 'La inmovilización es la retención del vehículo en instalaciones oficiales hasta que se subsane la infracción (SOAT, revisión técnica, etc.).', true),
  ('Conducción Segura', 'Al conducir en una pendiente pronunciada hacia abajo, ¿qué técnica ayuda a controlar la velocidad sin sobrecalentar los frenos?', '["Frenar constantemente", "Apagar el motor", "Bajar marchas para usar el freno motor", "Acelerar controladamente"]'::jsonb, 2, 'En pendientes largas se debe usar el freno motor (bajar marchas) para controlar la velocidad y evitar sobrecalentar los frenos de disco o tambor.', true);